              background-color: #007bff;
              color: white;
              border: none;
              border-radius: 4px;
              cursor: pointer;
              font-size: 14px;
            }
            .copy-button:hover {
              background-color: #0056b3;
            }
            .snackbar {
              visibility: hidden;
              min-width: 250px;
              background-color: #323232;
              color: #fff;
              text-align: center;
              border-radius: 2px;
              padding: 16px;
              position: fixed;
              z-index: 1;
              left: 50%;
              bottom: 30px;
              transform: translateX(-50%);
              font-size: 17px;
              animation: fadein 0.5s, fadeout 0.5s 2.5s;
            }
            .snackbar.show {
              visibility: visible;
            }
            @keyframes fadein {
              from {
                bottom: 0;
                opacity: 0;
              }
              to {
                bottom: 30px;
                opacity: 1;
              }
            }
            @keyframes fadeout {
              from {
                bottom: 30px;
                opacity: 1;
              }
              to {
                bottom: 0;
                opacity: 0;
