        </head>
        <body>
          <h1>Copy to Clipboard Demo</h1>
          <div class="copy-container">
            <div class="copy-text" id="copyText">Hello, this is the text to copy!</div>
            <button class="copy-button" id="copyButton">Copy Text</button>
