          <div class="copy-container">
            <input type="text" id="copyInput" value="Input text to copy" style="padding: 10px; width: 300px; font-size: 14px;">
            <button class="copy-button" id="copyInputButton">Copy Input</button>
          </div>

          <div id="snackbar" class="snackbar" role="status" aria-live="polite" aria-atomic="true">
            Text copied to clipboard!
          </div>

          <script>
            function showSnackbar() {
              const snackbar = document.getElementById('snackbar');
              snackbar.classList.add('show');
              setTimeout(() => {
                snackbar.classList.remove('show');
              }, 3000);
            }

            document.getElementById('copyButton').addEventListener('click', async () => {
              const text = document.getElementById('copyText').textContent;
              try {
                await navigator.clipboard.writeText(text);
                showSnackbar();
              } catch (err) {
                console.error('Failed to copy:', err);
              }
            });

            document.getElementById('copyInputButton').addEventListener('click', async () => {
              const text = document.getElementById('copyInput').value;
              try {
                await navigator.clipboard.writeText(text);
                showSnackbar();
              } catch (err) {
                console.error('Failed to copy:', err);
              }
            });
          </script>
        </body>
      </html>
    `);
  });

